package run.ikaros.finance; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class TransactionTagService{private final FinanceTransactionRepository transactions;private final FinanceTagRepository tags;private final TransactionTagRepository links;public TransactionTagService(FinanceTransactionRepository t,FinanceTagRepository g,TransactionTagRepository l){transactions=t;tags=g;links=l;}public Mono<TransactionTagView> add(UUID a,UUID transactionId,TagTransactionRequest q){return transactions.findById(transactionId).filter(t->t.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Transaction 不存在或无权访问"))).flatMap(t->tags.findById(q.tagId()).filter(tag->tag.ownerId().equals(a)&&tag.ledgerId().equals(t.ledgerId())).switchIfEmpty(Mono.error(new NotFoundException("Tag 不存在或不属于该 Ledger"))).flatMap(tag->links.findByTransactionIdAndTagIdAndOwnerId(transactionId,q.tagId(),a).flatMap(old->Mono.<TransactionTagEntity>error(new ConflictException("Transaction 已绑定该 Tag"))).switchIfEmpty(links.save(new TransactionTagEntity(null,transactionId,q.tagId(),t.ledgerId(),a,Instant.now()))))).map(this::view);}public Flux<TransactionTagView> list(UUID a,UUID transactionId){return transactions.findById(transactionId).filter(t->t.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Transaction 不存在或无权访问"))).flatMapMany(t->links.findAllByTransactionIdAndOwnerId(transactionId,a).map(this::view));}public Mono<Void> remove(UUID a,UUID transactionId,UUID tagId){return transactions.findById(transactionId).filter(t->t.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Transaction 不存在或无权访问"))).then(links.findByTransactionIdAndTagIdAndOwnerId(transactionId,tagId,a).switchIfEmpty(Mono.error(new NotFoundException("Transaction Tag 不存在"))).flatMap(links::delete)).then();}private TransactionTagView view(TransactionTagEntity x){return new TransactionTagView(x.id(),x.transactionId(),x.tagId(),x.createdAt());}}
